def valid_decomposable_string(s):
    pairs = 0
    index = 0
    while index < len(s):
        end = index + 1
        while end < len(s) and s[end] == s[index]:
            end += 1
        remainder = (end - index) % 3
        if remainder == 1:
            return False
        if remainder == 2:
            pairs += 1
        index = end
    return pairs == 1

